import { LazyImage } from "./lazy-image";

export function ImageGallery() {
  return (
    <div className="relative flex min-h-screen w-full flex-col items-center justify-center px-4 py-10">
      <div className="mx-auto grid w-full max-w-5xl grid-cols-1 gap-4 sm:grid-cols-2 md:grid-cols-4 md:gap-6">
        {Array.from({ length: 4 }).map((_, col) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: fixed gallery layout
          <div className="grid gap-4" key={`col-${col}`}>
            {/* biome-ignore lint/nursery/noShadow: false positive */}
            {Array.from({ length: 8 }).map((_, index) => {
              const isPortrait = Math.random() > 0.5;
              const width = isPortrait ? 1080 : 1920;
              const height = isPortrait ? 1920 : 1080;
              const ratio = isPortrait ? 9 / 16 : 16 / 9;

              return (
                <LazyImage
                  alt={`Image ${col}-${index}`}
                  fallback={`https://placehold.co/${width}x${height}/`}
                  inView={true}
                  // biome-ignore lint/suspicious/noArrayIndexKey: fixed gallery image seed
                  key={`img-${col}-${index}`}
                  ratio={ratio}
                  src={`https://picsum.photos/seed/${col}-${index}/${width}/${height}`}
                />
              );
            })}
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useInView } from "motion/react";
import React from "react";
import { AspectRatio } from "@/components/ui/aspect-ratio";
import { cn } from "@/lib/utils";

type LazyImageProps = {
  alt: string;
  src: string;
  className?: string;
  AspectRatioClassName?: string;
  /** URL of the fallback image. default: undefined */
  fallback?: string;
  /** The ratio of the image. */
  ratio: number;
  /** Whether the image should only load when it is in view. default: false */
  inView?: boolean;
};

export function LazyImage({
  alt,
  src,
  ratio,
  fallback,
  inView = false,
  className,
  AspectRatioClassName,
}: LazyImageProps) {
  const ref = React.useRef<HTMLDivElement | null>(null);
  const imgRef = React.useRef<HTMLImageElement | null>(null);
  const isInView = useInView(ref, { once: true });

  const [imgSrc, setImgSrc] = React.useState<string | undefined>(
    inView ? undefined : src
  );
  const [isLoading, setIsLoading] = React.useState(true);

  const handleError = () => {
    if (fallback) {
      setImgSrc(fallback);
    }
    setIsLoading(false);
  };

  const handleLoad = React.useCallback(() => {
    setIsLoading(false);
  }, []);

  // Load image only when inView
  React.useEffect(() => {
    if (inView && isInView && !imgSrc) {
      setImgSrc(src);
    }
  }, [inView, isInView, src, imgSrc]);

  // Handle cached images instantly
  React.useEffect(() => {
    if (imgRef.current?.complete) {
      handleLoad();
    }
  }, [handleLoad]);

  return (
    <AspectRatio
      className={cn(
        "relative size-full overflow-hidden rounded-lg border bg-accent/30",
        AspectRatioClassName
      )}
      ratio={ratio}
      ref={ref}
    >
      {imgSrc && (
        // biome-ignore lint/correctness/useImageSize: dynamic image size
        <img
          alt={alt}
          className={cn(
            "size-full rounded-md object-cover transition-opacity duration-500",
            isLoading ? "opacity-0" : "opacity-100",
            className
          )}
          decoding="async"
          fetchPriority={inView ? "high" : "low"}
          loading="lazy"
          onError={handleError}
          onLoad={handleLoad}
          ref={imgRef}
          role="presentation" // Changed from "img" to "presentation" since it's decorative
          src={imgSrc}
        />
      )}
    </AspectRatio>
  );
}
